<template>
  <el-dialog
    v-model="visible"
    :title="isEdit ? t('notifier.channelForm.editTitle') : t('notifier.channelForm.createTitle')"
    width="680px"
    :close-on-click-modal="false"
    @closed="onClosed"
  >
    <el-form ref="formRef" :model="form" :rules="rules" label-width="100px">
      <el-form-item :label="t('common.name')" prop="name">
        <el-input v-model="form.name" :placeholder="t('notifier.channelForm.namePlaceholder')" />
      </el-form-item>
      <el-form-item :label="t('common.type')" prop="channel_type">
        <el-radio-group v-model="form.channel_type" @change="onTypeChange">
          <el-radio value="email">{{ t('notifier.channelForm.email') }}</el-radio>
          <el-radio value="webhook">Webhook</el-radio>
        </el-radio-group>
      </el-form-item>
      <el-form-item :label="t('notifier.channelForm.configJson')" prop="config">
        <JsonEditor
          v-model="form.config"
          :rows="8"
          :placeholder="configPlaceholder"
        />
      </el-form-item>
      <el-form-item :label="t('common.enable')">
        <el-switch v-model="form.enabled" />
      </el-form-item>
    </el-form>

    <template #footer>
      <el-button @click="visible = false">{{ t('common.cancel') }}</el-button>
      <el-button type="primary" :loading="submitting" @click="onSubmit">
        {{ isEdit ? t('common.save') : t('common.create') }}
      </el-button>
    </template>
  </el-dialog>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import {
  createNotificationChannel,
  updateNotificationChannel,
  type NotificationChannelCreate,
  type NotificationChannelRead,
  type NotificationChannelType,
} from '@/api/notificationChannels'
import JsonEditor from '@/components/common/JsonEditor.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()

const props = defineProps<{
  modelValue: boolean
  channel?: NotificationChannelRead | null
}>()

const emit = defineEmits<{
  'update:modelValue': [value: boolean]
  success: []
}>()

const visible = ref(props.modelValue)
const submitting = ref(false)
const formRef = ref<FormInstance>()
const isEdit = ref(false)

const form = ref<{
  name: string
  channel_type: NotificationChannelType
  config: Record<string, unknown>
  enabled: boolean
}>({
  name: '',
  channel_type: 'email',
  config: {},
  enabled: true,
})

const configPlaceholder = computed(() => {
  if (form.value.channel_type === 'email') {
    return JSON.stringify(
      {
        smtp_host: 'smtp.example.com',
        smtp_port: 587,
        username: 'alert@example.com',
        password: 'your-password',
        use_tls: true,
        from_addr: 'alert@example.com',
      },
      null,
      2
    )
  }
  return JSON.stringify(
    {
      url: 'https://example.com/webhook',
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      timeout: 30,
    },
    null,
    2
  )
})

const rules: FormRules = {
  name: [{ required: true, message: () => t('notifier.channelForm.nameRequired'), trigger: 'blur' }],
  channel_type: [{ required: true, message: () => t('notifier.channelForm.typeRequired'), trigger: 'change' }],
  config: [{ required: true, message: () => t('notifier.channelForm.configRequired'), trigger: 'blur' }],
}

watch(
  () => props.modelValue,
  (val) => {
    visible.value = val
  }
)

watch(
  () => props.channel,
  (channel) => {
    if (channel) {
      isEdit.value = true
      form.value = {
        name: channel.name,
        channel_type: channel.channel_type,
        config: channel.config || {},
        enabled: channel.enabled,
      }
    } else {
      isEdit.value = false
      resetForm()
    }
  },
  { immediate: true }
)

function onTypeChange() {
  form.value.config = {}
}

function resetForm() {
  form.value = {
    name: '',
    channel_type: 'email',
    config: {},
    enabled: true,
  }
}

function onClosed() {
  emit('update:modelValue', false)
  formRef.value?.resetFields()
  resetForm()
}

async function onSubmit() {
  const valid = await formRef.value?.validate().catch(() => false)
  if (!valid) return

  submitting.value = true
  try {
    const data: NotificationChannelCreate = {
      name: form.value.name,
      channel_type: form.value.channel_type,
      config: form.value.config,
      enabled: form.value.enabled,
    }
    if (props.channel) {
      await updateNotificationChannel(props.channel.id, data)
    } else {
      await createNotificationChannel(data)
    }
    ElMessage.success(isEdit.value ? t('notifier.channelUpdated') : t('notifier.channelCreated'))
    emit('success')
    visible.value = false
  } catch (error) {
    showError(error, isEdit.value ? t('notifier.updateChannelFailed') : t('notifier.createChannelFailed'))
  } finally {
    submitting.value = false
  }
}
</script>
